import bpy, mathutils
# feet chunkier
for name in ["Foot_R","Foot_L"]:
    o=bpy.data.objects.get(name)
    if o: o.scale=(1.18,1.05,1.28)
for name in ["Sole_R","Sole_L"]:
    o=bpy.data.objects.get(name)
    if o: o.scale=(1.15,1.03,1.0)
# teeth narrower
for i in range(2):
    t=bpy.data.objects.get("Tooth"+str(i))
    if t: t.dimensions=(0.052,0.022,0.055)

# straighten lower body a touch: replace LowerBody
old=bpy.data.objects.get("LowerBody")
mat=None
if old:
    mat=old.data.materials[0] if old.data.materials else None
    bpy.data.objects.remove(old, do_unlink=True)
bpy.ops.mesh.primitive_cone_add(vertices=64, radius1=0.84, radius2=0.795, depth=0.82, location=(0,0,0.57))
nb=bpy.context.active_object; nb.name="LowerBody"
if mat: nb.data.materials.append(mat)
for p in nb.data.polygons: p.use_smooth=True
m=nb.modifiers.new("bev",'BEVEL'); m.width=0.035; m.segments=3

cam=bpy.data.objects["Camera"]
def render_to(path, loc, target=(0,0,0.8)):
    cam.location=loc
    d=mathutils.Vector(target)-cam.location; cam.rotation_euler=d.to_track_quat('-Z','Y').to_euler()
    bpy.context.scene.render.filepath=path; bpy.ops.render.render(write_still=True)

